function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100) return 'arr needs 2 to 100 strings.';
  for (const word of arr) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 20) return 'Each string has 1 to 20 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Strings use only lowercase English letters.';
  }
  return null;
}

