function shortestSubstrings(arr) {
  const owners = new Map();
  for (const word of arr) {
    const seen = new Set();
    for (let start = 0; start < word.length; start++) {
      for (let end = start + 1; end <= word.length; end++) {
        seen.add(word.slice(start, end));
      }
    }
    for (const sub of seen) {
      owners.set(sub, (owners.get(sub) ?? 0) + 1);
    }
  }

  const answer = [];
  for (const word of arr) {
    let best = '';
    for (let length = 1; length <= word.length && best === ''; length++) {
      for (let start = 0; start + length <= word.length; start++) {
        const sub = word.slice(start, start + length);
        if (owners.get(sub) === 1 && (best === '' || sub < best)) {
          best = sub;
        }
      }
    }
    answer.push(best);
  }
  return answer;
}

