function shortestSubstrings(arr) {
  // For each string, test every substring against every other string with includes, then sort the survivors.
  return arr.map((word, i) => {
    const unique = [];
    for (let a = 0; a < word.length; a++) {
      for (let b = a + 1; b <= word.length; b++) {
        const piece = word.substring(a, b);
        if (arr.every((other, j) => j === i || !other.includes(piece))) unique.push(piece);
      }
    }
    unique.sort((x, y) => x.length - y.length || (x < y ? -1 : x > y ? 1 : 0));
    return unique.length ? unique[0] : '';
  });
}

