function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const large = size === 'large';
  const n = large ? 60 + pick(41) : 2 + pick(5);
  const letters = large ? 2 + pick(5) : 1 + pick(3);
  const longest = large ? 20 : 1 + pick(6);
  const word = () => Array.from({ length: 1 + pick(longest) }, () => String.fromCharCode(97 + pick(letters))).join('');
  const arr = [];
  for (let i = 0; i < n; i++) {
    // Sometimes repeat or trim an earlier string so that shared substrings and empty answers show up.
    const roll = rand();
    if (arr.length && roll < 0.15) arr.push(arr[pick(arr.length)]);
    else if (arr.length && roll < 0.3) {
      const base = arr[pick(arr.length)];
      const from = pick(base.length);
      arr.push(base.slice(from, from + 1 + pick(base.length - from)));
    } else arr.push(word());
  }
  return [arr];
}
